fe-race:
useEffect(() => {
  let active = true;
  async function load() {
    try {
      const data = await fetchResults(query);
      if (active) setResult(data);
    } catch (error) {
      if (active) setError(error);
    }
  }
  load();
  return () => { active = false; };
}, [query]);
// 示例以忽略过期结果兜底；真实页面还应管理 loading、错误重置和可取消请求。

